<h1><?= $v->e($v->t('system')) ?></h1><div class="actions"><form method="post" action="/system/test-telegram"><?= $v->csrf() ?><button><?= $v->e($v->t('test_telegram')) ?></button></form><form method="post" action="/system/test-mail"><?= $v->csrf() ?><button><?= $v->e($v->t('test_mail')) ?></button></form></div>
<?php foreach ($data as $key=>$value): ?><section class="card"><h2><?= $v->e($v->t($key)) ?></h2><?php if (is_array($value)): ?><?php if (array_is_list($value)): ?><?= $v->table($value) ?><?php else: ?><dl><?php foreach ($value as $name=>$fact): ?><dt><?= $v->e($name) ?></dt><dd><?= $v->e(is_array($fact)?json_encode($fact,JSON_UNESCAPED_UNICODE):(is_bool($fact)?($fact?'✓':'✗'):$fact)) ?></dd><?php endforeach ?></dl><?php endif ?><?php else: ?><p><?= $v->e(is_bool($value)?($value?'✓':'✗'):$value) ?></p><?php endif ?></section><?php endforeach ?>
